// Approach: A binary heap keeps its maximum (or minimum) at the root. Priority queues support
//   constant-time top and logarithmic push/pop.
#include <queue>
#include <vector>
using namespace std;
vector<int> descendingByPriority(const vector<int>& values) {
    priority_queue<int> maxHeap;
    for (int value : values) maxHeap.push(value);
    vector<int> answer;
    while (!maxHeap.empty()) {
        answer.push_back(maxHeap.top());
        maxHeap.pop();
    }
    return answer;
}

s11-min-heap-and-max-heap-implementation.code:
// Approach: Store the complete binary tree in an array. Sift a new value upward on push; after
//   removing the root, sift the replacement downward.
#include <stdexcept>
#include <vector>
#include <utility>
using namespace std;
class BinaryHeap {
    vector<int> a;
    bool minHeap;
    bool higher(int x, int y) const {
        return minHeap ? x < y : x > y;
    }
public:
    explicit BinaryHeap(bool makeMinHeap) : minHeap(makeMinHeap) {}
    bool empty() const { return a.empty(); }
    int top() const {
        if (a.empty()) throw underflow_error("heap empty");
        return a[0];
    }
    void push(int value) {
        a.push_back(value);
        int i = (int)a.size() - 1;
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (!higher(a[i], a[parent])) break;
            swap(a[i], a[parent]);
            i = parent;
        }
    }
    int pop() {
        if (a.empty()) throw underflow_error("heap empty");
        int result = a[0];
        a[0] = a.back();
        a.pop_back();
        int n = (int)a.size(), i = 0;
        while (true) {
            int best = i, left = 2 * i + 1, right = left + 1;
            if (left < n && higher(a[left], a[best])) best = left;
            if (right < n && higher(a[right], a[best])) best = right;
            if (best == i) break;
            swap(a[i], a[best]);
            i = best;
        }
        return result;
    }
};

s11-check-if-an-array-represents-a-min-h.code:
// Approach: A min-heap requires every parent to be no greater than its children. Check each non-root
//   node against its parent.
#include <vector>
using namespace std;
bool isMinHeap(const vector<int>& a) {
    for (int child = 1; child < (int)a.size(); ++child)
        if (a[(child - 1) / 2] > a[child]) return false;
    return true;
}

s11-convert-min-heap-to-max-heap.code:
// Approach: Bottom-up heapify: sift down every internal node, starting from the last parent. This
//   builds a max-heap in linear time.
#include <algorithm>
#include <vector>
using namespace std;
void siftDownMax(vector<int>& a, int i) {
    int n = (int)a.size();
    while (true) {
        int largest = i, left = 2 * i + 1, right = left + 1;
        if (left < n && a[left] > a[largest]) largest = left;
        if (right < n && a[right] > a[largest]) largest = right;
        if (largest == i) break;
        swap(a[i], a[largest]);
        i = largest;
    }
}
void convertToMaxHeap(vector<int>& a) {
    for (int i = (int)a.size() / 2 - 1; i >= 0; --i)
        siftDownMax(a, i);
}

s11-kth-largest-element-in-an-array-use-.code:
// Approach: Keep the k largest values in a min-heap. Its root is the kth largest after all elements
//   are processed.
#include <functional>
#include <queue>
#include <stdexcept>
#include <vector>
using namespace std;
int kthLargest(const vector<int>& a, int k) {
    if (k < 1 || k > (int)a.size()) throw invalid_argument("invalid k");
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int value : a) {
        heap.push(value);
        if ((int)heap.size() > k) heap.pop();
    }
    return heap.top();
}

