s11-sort-k-sorted-array.code:
// Approach: In a k-sorted array, the next smallest element must be among the next k+1 input
//   positions. Keep those candidates in a min-heap.
#include <functional>
#include <queue>
#include <vector>
using namespace std;
vector<int> sortNearlySorted(const vector<int>& a, int k) {
    if (k < 0) return {};
    priority_queue<int, vector<int>, greater<int>> heap;
    vector<int> answer;
    for (int value : a) {
        heap.push(value);
        if ((int)heap.size() > k) {
            answer.push_back(heap.top());
            heap.pop();
        }
    }
    while (!heap.empty()) {
        answer.push_back(heap.top());
        heap.pop();
    }
    return answer;
}

s11-merge-m-sorted-lists.code:
// Approach: Put each nonempty list's head in a min-heap. Repeatedly append the smallest node and
//   insert its successor.
#include <queue>
#include <vector>
using namespace std;
struct ListNode { int val; ListNode* next; };
ListNode* mergeSortedLists(const vector<ListNode*>& lists) {
    struct Greater {
        bool operator()(const ListNode* a, const ListNode* b) const {
            return a->val > b->val;
        }
    };
    priority_queue<ListNode*, vector<ListNode*>, Greater> heap;
    for (ListNode* head : lists) if (head) heap.push(head);
    ListNode dummy{0, nullptr};
    ListNode* tail = &dummy;
    while (!heap.empty()) {
        ListNode* node = heap.top();
        heap.pop();
        if (node->next) heap.push(node->next);
        tail->next = node;
        tail = node;
    }
    tail->next = nullptr;
    return dummy.next;
}

s11-replace-each-array-element-by-its-co.code:
// Approach: Sort and deduplicate a copy. An element's rank is its lower-bound position in that sorted
//   list plus one.
#include <algorithm>
#include <vector>
using namespace std;
vector<int> replaceWithRanks(const vector<int>& a) {
    vector<int> sorted = a;
    sort(sorted.begin(), sorted.end());
    sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
    vector<int> answer;
    for (int value : a)
        answer.push_back((int)(lower_bound(sorted.begin(), sorted.end(), value)
                               - sorted.begin()) + 1);
    return answer;
}

s11-task-scheduler.code:
// Approach: The most frequent task creates maxFrequency−1 gaps of length cooldown+1. Tasks tied for
//   maximum frequency occupy the final slots.
#include <algorithm>
#include <array>
#include <vector>
using namespace std;
int leastInterval(const vector<char>& tasks, int cooldown) {
    if (tasks.empty()) return 0;
    array<int, 26> frequency{};
    for (char task : tasks) ++frequency[task - 'A']; // uppercase A-Z
    int highest = *max_element(frequency.begin(), frequency.end());
    int tied = 0;
    for (int count : frequency) if (count == highest) ++tied;
    int minimumSlots = (highest - 1) * (cooldown + 1) + tied;
    return max((int)tasks.size(), minimumSlots);
}

s11-hands-of-straights.code:
// Approach: Always start with the smallest remaining card. Remove one copy of each of the next
//   groupSize consecutive values; any missing value makes grouping impossible.
#include <map>
#include <vector>
using namespace std;
bool isNStraightHand(const vector<int>& hand, int groupSize) {
    if (groupSize <= 0 || hand.size() % groupSize != 0) return false;
    map<long long, int> count;
    for (int card : hand) ++count[card];
    while (!count.empty()) {
        long long start = count.begin()->first;
        for (int offset = 0; offset < groupSize; ++offset) {
            auto it = count.find(start + offset);
            if (it == count.end()) return false;
            if (--it->second == 0) count.erase(it);
        }
    }
    return true;
}

s11-design-twitter.code:
// Approach: Store each user's tweets in time order. To build a feed, heap-merge the latest tweet from
//   the user and every followee, taking only ten posts.
#include <queue>
#include <unordered_map>
#include <unordered_set>
#include <vector>
using namespace std;
class Twitter {
    struct Tweet { long long time; int id; };
    struct FeedItem {
        long long time;
        int user, index, id;
        bool operator<(const FeedItem& other) const {
            return time < other.time;
        }
    };
    long long clock = 0;
    unordered_map<int, vector<Tweet>> tweets;
    unordered_map<int, unordered_set<int>> following;
public:
    void postTweet(int userId, int tweetId) {
        tweets[userId].push_back({++clock, tweetId});
    }
    void follow(int followerId, int followeeId) {
        if (followerId != followeeId)
            following[followerId].insert(followeeId);
    }
    void unfollow(int followerId, int followeeId) {
        auto it = following.find(followerId);
        if (it != following.end()) it->second.erase(followeeId);
    }
    vector<int> getNewsFeed(int userId) {
        priority_queue<FeedItem> heap;
        auto addLatest = [&](int user) {
            auto it = tweets.find(user);
            if (it == tweets.end() || it->second.empty()) return;
            int index = (int)it->second.size() - 1;
            const Tweet& t = it->second[index];
            heap.push({t.time, user, index, t.id});
        };
        addLatest(userId);
        auto it = following.find(userId);
        if (it != following.end())
            for (int user : it->second) addLatest(user);
        vector<int> feed;
        while (!heap.empty() && feed.size() < 10) {
            FeedItem current = heap.top();
            heap.pop();
            feed.push_back(current.id);
            if (current.index > 0) {
                int earlier = current.index - 1;
                const Tweet& t = tweets[current.user][earlier];
                heap.push({t.time, current.user, earlier, t.id});
            }
        }
        return feed;
    }
};

s11-connect-n-ropes-with-minimal-cost.code:
// Approach: Always join the two shortest ropes first. Their combined length is paid now and can be
//   reused in later joins.
#include <functional>
#include <queue>
#include <vector>
using namespace std;
long long minCostToConnectRopes(const vector<int>& ropes) {
    priority_queue<long long, vector<long long>, greater<long long>>
        heap(ropes.begin(), ropes.end());
    long long cost = 0;
    while (heap.size() > 1) {
        long long first = heap.top(); heap.pop();
        long long second = heap.top(); heap.pop();
        long long joined = first + second;
        cost += joined;
        heap.push(joined);
    }
    return cost;
}

s11-kth-largest-element-in-a-stream-of-r.code:
// Approach: Maintain a min-heap of the k largest values seen so far. After each insertion, its root
//   is the kth largest.
#include <functional>
#include <queue>
#include <stdexcept>
#include <vector>
using namespace std;
class KthLargest {
    int k;
    priority_queue<int, vector<int>, greater<int>> heap;
public:
    KthLargest(int k, const vector<int>& initial) : k(k) {
        if (k <= 0) throw invalid_argument("k must be positive");
        for (int value : initial) add(value);
    }
    int add(int value) {
        heap.push(value);
        if ((int)heap.size() > k) heap.pop();
        return heap.top();
    }
};

s11-maximum-sum-combination.code:
// Approach: Sort both arrays descending and start at pair (0,0). Pop the largest sum, then try its
//   right and down neighbors once each.
#include <algorithm>
#include <queue>
#include <set>
#include <tuple>
#include <vector>
using namespace std;
vector<long long> maxSumCombinations(vector<int> a, vector<int> b, int count) {
    vector<long long> answer;
    if (a.empty() || b.empty() || count <= 0) return answer;
    sort(a.rbegin(), a.rend());
    sort(b.rbegin(), b.rend());
    using Item = tuple<long long, int, int>; // sum, index in a, index in b
    priority_queue<Item> heap;
    set<pair<int,int>> seen;
    heap.push({(long long)a[0] + b[0], 0, 0});
    seen.insert({0, 0});
    while (!heap.empty() && (int)answer.size() < count) {
        auto [sum, i, j] = heap.top();
        heap.pop();
        answer.push_back(sum);
        if (i + 1 < (int)a.size() && seen.insert({i + 1, j}).second)
            heap.push({(long long)a[i + 1] + b[j], i + 1, j});
        if (j + 1 < (int)b.size() && seen.insert({i, j + 1}).second)
            heap.push({(long long)a[i] + b[j + 1], i, j + 1});
    }
    return answer;
}

s11-find-median-from-data-stream.code:
// Approach: Keep the lower half in a max-heap and upper half in a min-heap. Rebalance so the lower
//   heap has either equal size or one extra.
#include <functional>
#include <queue>
#include <stdexcept>
#include <vector>
using namespace std;
class MedianFinder {
    priority_queue<int> lower;
    priority_queue<int, vector<int>, greater<int>> upper;
public:
    void addNum(int value) {
        lower.push(value);
        upper.push(lower.top());
        lower.pop();
        if (lower.size() < upper.size()) {
            lower.push(upper.top());
            upper.pop();
        }
    }
    double findMedian() const {
        if (lower.empty()) throw underflow_error("no numbers");
        if (lower.size() > upper.size()) return lower.top();
        return ((long long)lower.top() + upper.top()) / 2.0;
    }
};

s11-k-most-frequent-elements.code:
// Approach: Count frequencies, then keep only the k most frequent distinct values in a min-heap.
//   Remove the smallest frequency when the heap grows.
#include <functional>
#include <queue>
#include <unordered_map>
#include <utility>
#include <vector>
using namespace std;
vector<int> topKFrequent(const vector<int>& a, int k) {
    if (k <= 0) return {};
    unordered_map<int, int> frequency;
    for (int value : a) ++frequency[value];
    using Item = pair<int,int>; // frequency, value
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    for (auto [value, count] : frequency) {
        heap.push({count, value});
        if ((int)heap.size() > k) heap.pop();
    }
    vector<int> answer;
    while (!heap.empty()) {
        answer.push_back(heap.top().second);
        heap.pop();
    }
    return answer;
}
